// Some portions generated by Claude
import { useMemo, type CSSProperties } from "react";
import { LEGEND_TYPE_LIMIT } from "./explorer-config.ts";
import type { GraphNode } from "./graph-types.ts";
import { primaryNodeType, typeVisual } from "./graph-visuals.ts";

export type StatusBarProps = {
  status: string;
  hasGraph: boolean;
  graphView: boolean;
  /** The drawn nodes: counted, and their types make up the legend. */
  drawnNodes: readonly GraphNode[];
  linkCount: number;
  statementCount: number;
  isTypeSelected: (typeId: string) => boolean;
  /** Whether any filter selects nodes: a chip then adds its type to the filters instead of selecting all of it. */
  filtersActive: boolean;
  /** Whether the type filter needs every selected type (set to "all") rather than one of them. */
  typeFilterNeedsAll?: boolean;
  onToggleType: (typeId: string) => void;
};

/** The line under the canvas: the latest status, the size of the drawn graph and the type legend. */
export function StatusBar({
  status,
  hasGraph,
  graphView,
  drawnNodes,
  linkCount,
  statementCount,
  isTypeSelected,
  filtersActive,
  typeFilterNeedsAll = false,
  onToggleType,
}: StatusBarProps) {
  const nodeCount = drawnNodes.length;
  const legendTypes = useMemo(() => {
    const counts = new Map<string, { id: string; label: string; count: number }>();
    drawnNodes.forEach((node) => {
      const type = primaryNodeType(node);
      if (!type) return;
      const current = counts.get(type.id);
      if (current) current.count += 1;
      else counts.set(type.id, { id: type.id, label: type.label, count: 1 });
    });
    return [...counts.values()]
      .sort((left, right) => right.count - left.count || left.label.localeCompare(right.label))
      .slice(0, LEGEND_TYPE_LIMIT);
  }, [drawnNodes]);
  return (
    <footer className="graph-footer">
      <p className="status-line" key={status} title={status}>
        {status ? <span className="status-dot" /> : null}
        <span className="status-text">{status}</span>
      </p>
      {hasGraph ? (
        <span className="graph-stats">
          {graphView
            ? `${nodeCount.toLocaleString()} ${nodeCount === 1 ? "node" : "nodes"} · ${linkCount.toLocaleString()} ${linkCount === 1 ? "link" : "links"}`
            : `${statementCount.toLocaleString()} ${statementCount === 1 ? "statement" : "statements"}`}
        </span>
      ) : null}
      {graphView && legendTypes.length ? (
        <ul className="legend" aria-label="Node colours by type">
          {legendTypes.map((type) => {
            const active = isTypeSelected(type.id);
            return (
              <li key={type.id}>
                <button
                  type="button"
                  aria-pressed={Boolean(active)}
                  title={
                    active
                      ? `Take ${type.label} out of the selection`
                      : filtersActive
                        ? `Add ${type.label} to the type filter${typeFilterNeedsAll ? " (nodes need every selected type)" : ""}`
                        : `Select the ${type.count.toLocaleString()} ${type.label} ${type.count === 1 ? "node" : "nodes"}`
                  }
                  style={{ "--legend-color": typeVisual(type.id).stroke } as CSSProperties}
                  onClick={() => onToggleType(type.id)}
                >
                  <span className="legend-dot" aria-hidden="true" />
                  {type.label}
                </button>
              </li>
            );
          })}
        </ul>
      ) : null}
    </footer>
  );
}
